import json,math
names=("breadth","state","impulse")
data={n:json.load(open("inputs/"+n+".json")) for n in names}
trades={n:sorted(data[n]["trades"],key=lambda t:t["opened_at"]) for n in names}
start,finish=1602720000000,1767225600000
result={"scope":"diagnostic of factual standalone executed entries only, not all blocked signals or a simulated union","individual":{},"pairs":{}}
for n,tr in trades.items():
 assert all(t["opened_at"]<=t["closed_at"] for t in tr)
 assert all(a["closed_at"]<=b["opened_at"] for a,b in zip(tr,tr[1:]))
 result["individual"][n]={"N":len(tr),"time_exposed_fraction":sum(t["closed_at"]-t["opened_at"] for t in tr)/(finish-start)}
for a,b in (("breadth","impulse"),("state","impulse")):
 at,bt=trades[a],trades[b]
 def audit(entry,other):
  occupied=[t for t in other if t["opened_at"]<=entry["opened_at"]<=t["closed_at"]]
  return occupied
 a_out=sum(not audit(t,bt) for t in at);b_out=sum(not audit(t,at) for t in bt)
 simultaneous=[(x,y) for x in at for y in bt if x["opened_at"]==y["opened_at"]]
 overlap=sum(max(0,min(x["closed_at"],y["closed_at"])-max(x["opened_at"],y["opened_at"])) for x in at for y in bt)
 result["pairs"][a+"_"+b]={"a_entries_outside_b":a_out,"b_entries_outside_a":b_out,
  "same_close_entries":len(simultaneous),"same_close_same_side":sum(x["type"]==y["type"] for x,y in simultaneous),
  "same_close_opposite_side":sum(x["type"]!=y["type"] for x,y in simultaneous),
  "overlap_time_fraction":overlap/(finish-start),
  "boundary_policy":"occupied at both open and close instants, conservative no same-close reentry"}
json.dump(result,open("output/opportunity_timing.json","w"),indent=2)
print(json.dumps(result))
